import ollama, json

def weather(city: str) -> str:
    return f"sunny in {city}"

messages = [{"role": "user", "content": "Weather in Austin?"}]
tools = [{
    "type": "function",
    "function": {
        "name": "weather",
        "description": "Get weather",
        "parameters": {"type": "object", "properties": {"city": {"type": "string"}}, "required": ["city"]},
    },
}]
r = ollama.chat(model="llama3.2", messages=messages, tools=tools)
if r["message"].get("tool_calls"):
    for c in r["message"]["tool_calls"]:
        args = c["function"]["arguments"]
        messages.append(r["message"])
        messages.append({"role": "tool", "content": weather(**args)})
    r = ollama.chat(model="llama3.2", messages=messages)
print(r["message"]["content"])
